        for task in self.tasks:
            if task['id'] == task_id:
                task['status'] = 'completed'
                self._save_to_disk()
                return True
        return False

    def delete_task(self, task_id):
        initial_len = len(self.tasks)
        self.tasks = [t for t in self.tasks if t['id'] != task_id]
        if len(self.tasks) < initial_len:
            self._save_to_disk()
            return True
        return False

