                'Accept-Ranges': 'bytes',
                'Content-Length': str(end - start + 1),
                'Content-Type': 'video/mp4',
            }

            return Response(
                stream_with_context(response_body),
                status=206,
                headers=headers,
                direct_passthrough=True
            )

    def run(self, host='0.0.0.0', port=8080):

        self.app.run(host=host, port=port, threaded=True)

