class FitnessDataImporter(abc.ABC):

    @abc.abstractmethod
    def fetch_data(self, external_user_id: str) -> List[Dict[str, Any]]:
        pass

    @abc.abstractmethod
    def transform(self, raw_data: List[Dict[str, Any]]) -> List[Workout]:
