        self.assertEqual(garmin_workout.exercises[0].sets, 2)

if __name__ == "__main__":

    suite = unittest.TestLoader().loadTestsFromTestCase(TestWorkoutApp)
    unittest.TextTestRunner(verbosity=2).run(suite)


