    acc1 = Account(account_id="ACC-7788", owner_name="Brad Principal", balance=Decimal('5000.00'))
    card1 = Card(card_number="1234-5678-9012", encrypted_pin="1234", account_id="ACC-7788", expiry_date=datetime(2028, 1, 1))

