        if atm.withdraw_cash(withdrawal_amount):
            print(f"Successfully withdrew ${withdrawal_amount}")
            print(f"New Balance: ${atm.check_balance()}")

        atm.eject_card()
    else:
        print("Authentication Failed.")
    print(f"--- ATM Session End ---")

if __name__ == "__main__":
    run_system_demo()

