    def setUp(self):
        self.evaluator = ChessEvaluator()

    def test_initial_position(self):
        board = chess.Board()

        self.assertEqual(self.evaluator.evaluate(board), 0)

    def test_white_material_advantage(self):
        board = chess.Board()

